// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        vm.startPrank(caller);
        BankCaller bankCaller = new BankCaller();
        vm.stopPrank();

        uint before = c.tokenBalance(address(bankCaller));

        bool ok;
        try bankCaller.doAirDrop(c) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.tokenBalance(address(bankCaller)) == 20);
    }
}

contract BankCaller {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function doAirDrop(ModifierEntrancy c) external {
        c.airDrop();
    }
}
